// mmx-linux: watcher do workspace indexing para Linux.
// motivo: fs.watch(dir, {recursive:true}) no Linux é um polyfill JS (internal/fs/recursive_watch) que registra
// um watcher por arquivo/pasta (inclui node_modules/.venv/.git), re-varre a árvore a cada evento e emite um
// evento por entrada; no utility do local-runtime isso prendia a thread principal a ~100% de CPU, atrasando
// todos os timers (content-safety, token counter, eval upload) e resultando em "negado"/espera longa.
// aqui: watches NÃO recursivos só em pastas relevantes (poda antes de registrar), varredura assíncrona
// com yield, teto de pastas e filtro barato de eventos em pastas ignoradas.
import { watch } from 'node:fs';
import { readdir } from 'node:fs/promises';
import { EventEmitter } from 'node:events';
import path from 'node:path';

const SKIP_DIR_NAMES = new Set([
  '.git', '.worktrees', 'node_modules', '.pnpm-store', '.venv', 'venv', 'build_env', '__pycache__',
  '.pytest_cache', '.mypy_cache', '.ruff_cache', '.tox', '.nox', '.gradle', '.cache', 'dist', 'build',
  'out', 'coverage', 'logs', '.next', '.nuxt', '.turbo', '.svelte-kit', 'target',
]);
const MAX_DIRS = Number(process.env.MMX_WATCH_MAX_DIRS) || 3000;
const YIELD_EVERY = 64;

const isSkipped = (name) => SKIP_DIR_NAMES.has(name) || SKIP_DIR_NAMES.has(String(name).toLowerCase());
const hasSkippedSegment = (rel) => rel.split(path.sep).some(isSkipped);

class MmxWorkspaceWatcher extends EventEmitter {
  constructor(root, onChange) {
    super();
    this.root = root;
    this.onChange = onChange;
    this.closed = false;
    this.watchers = new Map();
    this.pending = new Set();
    this.walkChain = Promise.resolve();
    this.queue(root);
  }
  unref() { return this; }
  ref() { return this; }
  close() {
    if (this.closed) return;
    this.closed = true;
    for (const w of this.watchers.values()) { try { w.close(); } catch { /* já fechado */ } }
    this.watchers.clear();
    this.pending.clear();
  }
  queue(dir) {
    if (this.closed || this.watchers.has(dir) || this.pending.has(dir)) return;
    this.pending.add(dir);
    this.walkChain = this.walkChain.then(() => this.walk(dir)).catch(() => undefined);
  }
  async walk(start) {
    const stack = [start];
    let visited = 0;
    while (stack.length > 0 && !this.closed) {
      const dir = stack.pop();
      this.pending.delete(dir);
      if (this.watchers.has(dir) || this.watchers.size >= MAX_DIRS) continue;
      let entries;
      try { entries = await readdir(dir, { withFileTypes: true }); } catch { continue; }
      if (this.closed) return;
      if (!this.attach(dir)) continue;
      for (const entry of entries) {
        if (entry.isDirectory() && !isSkipped(entry.name)) stack.push(path.join(dir, entry.name));
      }
      if (++visited % YIELD_EVERY === 0) await new Promise((resolve) => setImmediate(resolve));
    }
  }
  attach(dir) {
    try {
      const watcher = watch(dir, { persistent: false, recursive: false }, (event, filename) => {
        if (this.closed) return;
        const name = filename == null ? '' : filename.toString();
        if (name && isSkipped(name)) return;
        const rel = path.relative(this.root, name ? path.join(dir, name) : dir);
        if (rel && hasSkippedSegment(rel)) return;
        if (event === 'rename' && name) this.queue(path.join(dir, name)); // pasta nova: registra (arquivo comum => readdir falha e é ignorado)
        this.onChange(rel || undefined);
      });
      watcher.on('error', () => {
        try { watcher.close(); } catch { /* ignore */ }
        if (this.watchers.get(dir) === watcher) this.watchers.delete(dir);
      });
      this.watchers.set(dir, watcher);
      return true;
    } catch (error) {
      if (error && error.code === 'ENOSPC' && this.listenerCount('error') > 0) this.emit('error', error);
      return false;
    }
  }
}

export function mmxWatchWorkspace(root, onChange, onError) {
  const watcher = new MmxWorkspaceWatcher(root, onChange);
  if (onError) watcher.on('error', onError);
  return watcher;
}
